package db

import (
	"context"
	"database/sql"
	"errors"
)

// IdempotencyRecord is generated by sqlc (models.go) from the
// idempotency_records migration. This file only adds the handwritten query
// methods (ClaimIdempotency, GetIdempotency, ...) and the operation_id column
// is typed pgtype.UUID to match the DB; the mapper in each command repository
// converts it to a string for the shared idempotency.Record.

// CompleteIdempotencyParams carries the write payload for CompleteIdempotency.
type CompleteIdempotencyParams struct {
	Scope           string `db:"scope" json:"scope"`
	IdempotencyKey  string `db:"idempotency_key" json:"idempotency_key"`
	RequestHash     string `db:"request_hash" json:"request_hash"`
	Status          string `db:"status" json:"status"`
	ResponsePayload []byte `db:"response_payload" json:"response_payload"`
	ResourceID      *int32 `db:"resource_id" json:"resource_id"`
}

const idempotencyColumns = `id, scope, idempotency_key, request_hash, operation_id, status, response_payload, resource_id, created_at, updated_at, expires_at`

const claimIdempotency = `
		INSERT INTO idempotency_records (scope, idempotency_key, request_hash, status)
		VALUES ($1, $2, $3, 'processing')
		ON CONFLICT (scope, idempotency_key) DO UPDATE
			SET request_hash = EXCLUDED.request_hash,
			    status = 'processing',
			    response_payload = NULL,
			    resource_id = NULL,
			    updated_at = current_timestamp,
			    expires_at = current_timestamp + INTERVAL '24 hours'
			WHERE idempotency_records.expires_at <= current_timestamp
		RETURNING ` + idempotencyColumns

const getIdempotency = `SELECT ` + idempotencyColumns + ` FROM idempotency_records WHERE scope=$1 AND idempotency_key=$2 AND expires_at > current_timestamp`

const completeIdempotency = `
		UPDATE idempotency_records
		SET status=$4, response_payload=$5, resource_id=$6, updated_at=current_timestamp
		WHERE scope=$1 AND idempotency_key=$2 AND request_hash=$3`

const releaseIdempotency = `DELETE FROM idempotency_records WHERE scope=$1 AND idempotency_key=$2 AND request_hash=$3 AND status='processing'`

// idempotencyQueryer is the executor surface needed by the idempotency
// queries. Both *sqlx.DB and *sqlx.Tx satisfy it.
type idempotencyQueryer interface {
	GetContext(ctx context.Context, dest interface{}, query string, args ...interface{}) error
	ExecContext(ctx context.Context, query string, args ...interface{}) (sql.Result, error)
}

// ClaimIdempotency atomically claims a key. sql.ErrNoRows means another request
// already owns the key (and it has not expired) and callers should load it with
// GetIdempotency. Expired records are reclaimed by the same request, so a client
// retry after the 24h window never double-executes against a stale claim.
func ClaimIdempotency(ctx context.Context, q idempotencyQueryer, scope, key, requestHash string) (*IdempotencyRecord, error) {
	var record IdempotencyRecord
	if err := q.GetContext(ctx, &record, claimIdempotency, scope, key, requestHash); err != nil {
		return nil, err
	}
	return &record, nil
}

func GetIdempotency(ctx context.Context, q idempotencyQueryer, scope, key string) (*IdempotencyRecord, error) {
	var record IdempotencyRecord
	if err := q.GetContext(ctx, &record, getIdempotency, scope, key); err != nil {
		return nil, err
	}
	return &record, nil
}

func CompleteIdempotency(ctx context.Context, q idempotencyQueryer, arg CompleteIdempotencyParams) error {
	_, err := q.ExecContext(ctx, completeIdempotency,
		arg.Scope, arg.IdempotencyKey, arg.RequestHash, arg.Status, arg.ResponsePayload, arg.ResourceID)
	return err
}

func ReleaseIdempotency(ctx context.Context, q idempotencyQueryer, scope, key, requestHash string) error {
	_, err := q.ExecContext(ctx, releaseIdempotency, scope, key, requestHash)
	return err
}

func IsIdempotencyMiss(err error) bool { return errors.Is(err, sql.ErrNoRows) }
